/**
 * Which way a Clairic extraction goes, decided from the environment alone.
 *
 * Shared by the `extraction` actions and by the persona research wiring in
 * `agents.ts`, which needs to know whether extraction is reachable without
 * crossing a function boundary to ask. The rules match `systemOne.ts`: Not
 * Organic wins whenever it is enabled; the direct Cloudflare credentials are a
 * local-development fallback that only unlocks on a loopback deployment.
 */
import { notOrganicEnabled } from "./notorganic";

export type ExtractionTransport = "notorganic" | "direct" | "none";

export function directExtractionCredentials(
  env: Readonly<Record<string, string | undefined>> = process.env,
): { token: string; account: string } | null {
  if (
    env.NODE_ENV !== "development" ||
    env.TWYNE_ALLOW_DIRECT_EXTRACTION !== "1"
  )
    return null;
  try {
    const url = new URL(env.CONVEX_CLOUD_URL ?? "");
    if (
      !["http:", "https:"].includes(url.protocol) ||
      !["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)
    )
      return null;
  } catch {
    return null;
  }
  const token = env.CLOUDFLARE_AI_API_TOKEN?.trim();
  const account = env.CLOUDFLARE_ACCOUNT_ID?.trim();
  return token && account ? { token, account } : null;
}

export function extractionTransport(
  env: Readonly<Record<string, string | undefined>> = process.env,
): ExtractionTransport {
  if (notOrganicEnabled(env)) return "notorganic";
  if (directExtractionCredentials(env)) return "direct";
  return "none";
}
